"""Fail when the pip-compatible production lock is stale or unsafe."""

from __future__ import annotations

# Subprocess is limited to fixed, shell-free uv validation commands below.
import subprocess  # nosec B404
import tempfile
from pathlib import Path

from validate_requirements_lock import validate_requirements_lock


REPOSITORY = Path(__file__).resolve().parents[1]
LOCK = REPOSITORY / "requirements.lock"
EXPECTED_HEADER = (
    "# This file was autogenerated by uv via the following command:\n"
    "#    uv export --frozen --no-dev --no-emit-project "
    "--format requirements.txt --output-file requirements.lock\n"
)
EXPORT_COMMAND = (
    "uv",
    "export",
    "--frozen",
    "--no-dev",
    "--no-emit-project",
    "--format",
    "requirements.txt",
)


def main() -> int:
    subprocess.run(  # nosec B603
        ("uv", "lock", "--check"),
        cwd=REPOSITORY,
        check=True,
    )
    with tempfile.TemporaryDirectory(prefix="strugglebus-lock-") as directory:
        generated = Path(directory) / "requirements.lock"
        subprocess.run(  # nosec B603
            (*EXPORT_COMMAND, "--output-file", str(generated)),
            cwd=REPOSITORY,
            check=True,
            stdout=subprocess.DEVNULL,
        )
        tracked_content = LOCK.read_text(encoding="utf-8")
        generated_content = generated.read_text(encoding="utf-8")
        if not tracked_content.startswith(EXPECTED_HEADER):
            raise RuntimeError(
                "requirements.lock does not record the reproducible export command"
            )
        if tracked_content.splitlines()[2:] != generated_content.splitlines()[2:]:
            raise RuntimeError(
                "requirements.lock is stale; regenerate it with the command "
                "recorded in its header"
            )

    validate_requirements_lock(LOCK)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
